<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Ubuntu Desktop</title>
  <style>
    * { box-sizing: border-box; }
    html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; font-family: Arial, sans-serif; }
    body { background: #17151f; color: #eee; }
    #desktop {
      position: relative;
      width: 100vw;
      height: 100vh;
      min-height: 480px;
      overflow: hidden;
      background:
        radial-gradient(circle at 72% 32%, rgba(157, 58, 112, .5), transparent 28%),
        radial-gradient(circle at 25% 75%, rgba(67, 40, 112, .55), transparent 34%),
        linear-gradient(135deg, #160e29, #351438 52%, #101b3a);
    }
    #desktop::before {
      content: "";
      position: absolute;
      inset: 0;
      opacity: .16;
      background: repeating-linear-gradient(125deg, transparent 0 35px, #fff 36px 37px, transparent 38px 78px);
      pointer-events: none;
    }
    #topbar {
      height: 34px;
      position: relative;
      z-index: 10;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 16px;
      background: rgba(20, 18, 25, .88);
      color: #f4f4f4;
      font-size: 13px;
      box-shadow: 0 1px 5px #0008;
    }
    .top-left { font-weight: bold; }
    .top-right { display: flex; gap: 18px; color: #ddd; }
    #taskbar {
      position: absolute;
      left: 50%;
      bottom: 14px;
      transform: translateX(-50%);
      z-index: 20;
      display: flex;
      gap: 8px;
      padding: 8px;
      border: 1px solid #ffffff22;
      border-radius: 14px;
      background: rgba(25, 21, 34, .86);
      box-shadow: 0 8px 28px #0008;
      backdrop-filter: blur(8px);
    }
    #taskbar button {
      width: 54px;
      height: 48px;
      border: 0;
      border-radius: 10px;
      color: #fff;
      background: #ffffff12;
      font-size: 24px;
      cursor: pointer;
      transition: background .15s, transform .15s;
    }
    #taskbar button:hover { background: #ffffff2b; transform: translateY(-2px); }
    .window {
      position: absolute;
      z-index: 5;
      display: none;
      flex-direction: column;
      width: 620px;
      height: 430px;
      min-width: 360px;
      min-height: 240px;
      overflow: hidden;
      border: 1px solid #ffffff33;
      border-radius: 9px;
      background: #24232b;
      box-shadow: 0 16px 45px #000a;
    }
    .window.open { display: flex; }
    #files-window { left: 10%; top: 12%; }
    #notepad-window { left: 25%; top: 18%; width: 650px; height: 440px; }
    .titlebar {
      height: 38px;
      flex: 0 0 38px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 10px 0 14px;
      background: linear-gradient(#4a4651, #38353e);
      cursor: move;
      user-select: none;
    }
    .title { font-size: 14px; font-weight: bold; }
    .win-close {
      width: 25px;
      height: 25px;
      border: 0;
      border-radius: 50%;
      color: #fff;
      background: #b74358;
      cursor: pointer;
      font-size: 16px;
      line-height: 25px;
    }
    .win-close:hover { background: #e05b70; }
    .files-toolbar {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 9px;
      background: #302e37;
      border-bottom: 1px solid #ffffff14;
    }
    .files-toolbar button {
      padding: 5px 11px;
      border: 1px solid #ffffff22;
      border-radius: 5px;
      color: #eee;
      background: #ffffff10;
      cursor: pointer;
    }
    .files-toolbar button:hover { background: #ffffff22; }
    #files-path {
      flex: 1;
      padding: 6px 9px;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
      border-radius: 4px;
      color: #ddd;
      background: #17161c;
      font-family: monospace;
    }
    #files-list {
      flex: 1;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
      align-content: start;
      gap: 7px;
      padding: 14px;
      overflow: auto;
      background: #292730;
    }
    .fs-item {
      min-height: 80px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 7px;
      padding: 8px;
      border-radius: 7px;
      color: #eee;
      cursor: default;
      text-align: center;
      word-break: break-word;
    }
    .fs-item:hover { background: #ffffff14; }
    .fs-icon { font-size: 31px; }
    #tabs {
      display: flex;
      align-items: center;
      gap: 2px;
      min-height: 37px;
      padding: 5px 7px 0;
      overflow-x: auto;
      background: #302e37;
    }
    .tab {
      max-width: 150px;
      padding: 8px 14px;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
      border: 0;
      border-radius: 6px 6px 0 0;
      color: #bbb;
      background: #25232b;
      cursor: pointer;
    }
    .tab.active { color: #fff; background: #111116; }
    #new-tab {
      flex: 0 0 auto;
      margin-left: 4px;
      padding: 6px 11px;
      border: 1px solid #ffffff26;
      border-radius: 5px;
      color: #fff;
      background: #ffffff12;
      cursor: pointer;
    }
    #new-tab:hover { background: #ffffff25; }
    #editor {
      flex: 1;
      width: 100%;
      resize: none;
      padding: 16px;
      outline: none;
      border: 0;
      color: #eee;
      background: #111116;
      font: 15px/1.5 Consolas, monospace;
    }
    .hint {
      position: absolute;
      top: 50%;
      left: 50%;
      color: #ffffff55;
      text-align: center;
      transform: translate(-50%, -50%);
      pointer-events: none;
    }
  </style>
</head>
<body>
  <main id="desktop">
    <header id="topbar">
      <div class="top-left">Activities</div>
      <div class="top-right"><span>Tue Aug 25</span><span>⌁  ☼  🔊  ▣</span></div>
    </header>

    <div class="hint">Welcome to your desktop</div>

    <section id="files-window" class="window" aria-label="Files">
      <div class="titlebar">
        <span class="title">Files</span>
        <button class="win-close" aria-label="Close">×</button>
      </div>
      <div class="files-toolbar">
        <button id="files-up" title="Parent folder">↑</button>
        <div id="files-path">/</div>
      </div>
      <div id="files-list"></div>
    </section>

    <section id="notepad-window" class="window" aria-label="Notepad">
      <div class="titlebar">
        <span class="title">Notepad</span>
        <button class="win-close" aria-label="Close">×</button>
      </div>
      <div id="tabs"></div>
      <textarea id="editor" spellcheck="false" aria-label="Text editor"></textarea>
    </section>

    <nav id="taskbar" aria-label="Application launchers">
      <button id="open-files" title="Open Files" aria-label="Open Files">🗂️</button>
      <button id="open-notepad" title="Open Notepad" aria-label="Open Notepad">📝</button>
    </nav>
  </main>

  <script>
    (() => {
      const desktop = document.getElementById("desktop");
      const filesWindow = document.getElementById("files-window");
      const notepadWindow = document.getElementById("notepad-window");
      const filesPath = document.getElementById("files-path");
      const filesList = document.getElementById("files-list");

      const fs = {
        "/": { bin: "dir", etc: "dir", home: "dir", usr: "dir", var: "dir" },
        "/bin": { bash: "file", ls: "file", cat: "file" },
        "/etc": { hosts: "file", passwd: "file", "os-release": "file" },
        "/home": { user: "dir" },
        "/home/user": { Documents: "dir", Downloads: "dir", Pictures: "dir", "readme.txt": "file" },
        "/home/user/Documents": { "notes.txt": "file", "report.pdf": "file" },
        "/home/user/Downloads": { "example.zip": "file" },
        "/home/user/Pictures": { "wallpaper.png": "file" },
        "/usr": { bin: "dir", lib: "dir", share: "dir" },
        "/var": { log: "dir", tmp: "dir" },
        "/var/log": { "system.log": "file" }
      };
      let currentPath = "/";

      function normalize(path) {
        if (!path || path === "/") return "/";
        return "/" + path.split("/").filter(Boolean).join("/");
      }

      function renderFiles() {
        filesPath.textContent = currentPath;
        filesList.innerHTML = "";
        const entries = fs[currentPath] || {};
        Object.keys(entries).sort((a, b) => {
          return entries[a] === entries[b] ? a.localeCompare(b) : entries[a] === "dir" ? -1 : 1;
        }).forEach(name => {
          const item = document.createElement("div");
          item.className = "fs-item";
          item.dataset.type = entries[name];
          item.dataset.name = name;
          item.innerHTML = `<span class="fs-icon">${entries[name] === "dir" ? "📁" : "📄"}</span><span>${name}</span>`;
          if (entries[name] === "dir") {
            item.addEventListener("dblclick", () => {
              currentPath = normalize(currentPath === "/" ? "/" + name : currentPath + "/" + name);
              renderFiles();
            });
          }
          filesList.appendChild(item);
        });
      }

      function showWindow(win) {
        win.classList.add("open");
        win.style.zIndex = ++showWindow.order;
      }
      showWindow.order = 10;

      document.getElementById("open-files").addEventListener("click", () => {
        showWindow(filesWindow);
        renderFiles();
      });
      document.getElementById("open-notepad").addEventListener("click", () => showWindow(notepadWindow));
      document.getElementById("files-up").addEventListener("click", () => {
        if (currentPath !== "/") {
          const parts = currentPath.split("/").filter(Boolean);
          parts.pop();
          currentPath = normalize(parts.join("/"));
          renderFiles();
        }
      });
      document.querySelectorAll(".win-close").forEach(button => {
        button.addEventListener("click", () => button.closest(".window").classList.remove("open"));
      });

      let tabs;
      try { tabs = JSON.parse(localStorage.getItem("ubuntu-notepad-tabs") || "null"); } catch (_) { tabs = null; }
      if (!Array.isArray(tabs) || !tabs.length) tabs = [{ name: "Untitled 1", content: "" }];
      let activeTab = Math.min(Number(localStorage.getItem("ubuntu-notepad-active") || 0), tabs.length - 1);
      const tabsEl = document.getElementById("tabs");
      const editor = document.getElementById("editor");

      function saveTabs() {
        localStorage.setItem("ubuntu-notepad-tabs", JSON.stringify(tabs));
        localStorage.setItem("ubuntu-notepad-active", String(activeTab));
      }
      function renderTabs() {
        tabsEl.innerHTML = "";
        tabs.forEach((tab, index) => {
          const el = document.createElement("button");
          el.className = "tab" + (index === activeTab ? " active" : "");
          el.textContent = tab.name;
          el.title = tab.name;
          el.addEventListener("click", () => {
            tabs[activeTab].content = editor.value;
            activeTab = index;
            editor.value = tabs[activeTab].content;
            renderTabs();
            saveTabs();
          });
          tabsEl.appendChild(el);
        });
        const add = document.createElement("button");
        add.id = "new-tab";
        add.textContent = "+";
        add.title = "New tab";
        add.addEventListener("click", () => {
          tabs[activeTab].content = editor.value;
          tabs.push({ name: "Untitled " + (tabs.length + 1), content: "" });
          activeTab = tabs.length - 1;
          editor.value = "";
          renderTabs();
          saveTabs();
          editor.focus();
        });
        tabsEl.appendChild(add);
      }
      editor.addEventListener("input", () => {
        tabs[activeTab].content = editor.value;
        saveTabs();
      });
      editor.value = tabs[activeTab].content;
      renderTabs();
      renderFiles();

      document.querySelectorAll(".titlebar").forEach(bar => {
        let dragging = false, offsetX = 0, offsetY = 0;
        bar.addEventListener("pointerdown", event => {
          const win = bar.closest(".window");
          dragging = true;
          showWindow(win);
          const rect = win.getBoundingClientRect();
          offsetX = event.clientX - rect.left;
          offsetY = event.clientY - rect.top;
          bar.setPointerCapture(event.pointerId);
        });
        bar.addEventListener("pointermove", event => {
          if (!dragging) return;
          const win = bar.closest(".window");
          const maxX = desktop.clientWidth - win.offsetWidth;
          const maxY = desktop.clientHeight - win.offsetHeight;
          win.style.left = Math.max(0, Math.min(maxX, event.clientX - offsetX)) + "px";
          win.style.top = Math.max(34, Math.min(maxY, event.clientY - offsetY)) + "px";
        });
        bar.addEventListener("pointerup", () => dragging = false);
        bar.addEventListener("pointercancel", () => dragging = false);
      });
    })();
  </script>
</body>
</html>
